    answer: "(a) In large multicellular organisms, simple diffusion is not enough. Respiratory pigment like haemoglobin picks up oxygen in lungs, carries it through blood to body tissues, and helps transport CO2 back to lungs. (b) 1. Cartilage rings keep trachea open and prevent collapse. 2. Residual volume allows continuous gas exchange between breaths and prevents lung collapse. 3. This increases chest cavity volume, reduces air pressure, allowing air to rush in. 4. Extensive network provides large surface area for efficient gas exchange."
