    question: "The mechanism by which sex of an individual is determined is called sex-determination. In humans, there are 46 (23 pairs) chromosomes - 44 autosomes and 2 sex chromosomes (X and Y). At fertilisation, the type of male gamete fusing with the female gamete decides the child\u0027s sex. (a) Why is the pair of sex chromosomes in males called a mismatched pair? (b) Which parent has a perfect pair of sex chromosomes? Will the gametes produced be of same kind or different? (c)(i) Name two animals whose sex is not genetically determined. Explain their sex determination. OR (ii) With a flowchart, show how sex is genetically determined in humans.",
    answer: "(a) In males, one sex chromosome is normal-sized X and the other is short Y, making them mismatched (heteromorphic). (b) Female has perfect pair (XX). All eggs carry X chromosome (same kind). (c)(i) Green sea turtle: temperature-dependent - cooler (~29Â°C) produces males, warmer (~33Â°C) produces females. Snail: individuals change sex - born male, later become female. OR (c)(ii) Female (XX) produces X eggs. Male (XY) produces X and Y sperms. X egg + X sperm = XX (female). X egg + Y sperm = XY (male)."
