    answer: "Overlapping differences lead to social division because some social differences overlap with other differences. They are difficult to accommodate. In Northern Ireland, Christians are divided between Catholics and Protestants. Here class and religion overlap with each other. Catholics are poor and have faced discrimination. This has resulted in conflicts. Cross-cutting differences do not lead to social divisions because it is difficult to pit one group of people against the other. They are easier to accommodate as in the case of Netherlands. In the Netherlands, class and religion tend to cut across each other. Catholics and Protestants are equally likely to be poor or rich. So they do not have conflicts so their differences are easily accommodated."
