    answer: "(i) Social divisions exist in most countries of the world. These divisions are reflected in politics. (ii) The assertion of social diversities in a country need not be seen as a source of danger because in a democracy, political expression of social divisions is very normal and can be healthy. This allows disadvantaged and marginal social groups to express their grievances and get the government to attend to these. (iii) In a democracy political parties discuss these divisions and make different promises to communities and make policies to redress the grievances of the disadvantaged communities. (iv) Expression of various kinds of social divisions in politics often results in their cancelling one another out and thus reducing their intensity. This leads to strengthening of a democracy."
