    answer: "The activities of pressure groups and movements exert influence on politics as well as democracy in a variety of ways: (i) By gaining public support and sympathy through information campaigns, organising meetings, filing petitions. (ii) By playing the role of invisible and unofficial government - they protect collective interests and try to influence those in power like ministers, bureaucrats and politicians. (iii) By forming linkage between masses and the elite - they articulate the claims of their members and become a means of communication between the masses and the elite. (iv) By organising protest activities in the form of strikes, hartals, bandhs. (v) By forming political parties and providing leadership - for example, the formation of Asom Gana Parishad out of the Assam Movement."
