    marks: 4,
    questionType: 'Long Answer',
    question: "What is the concept of mail merge in word processing software? Discuss in detail. Also give any two major benefits of using mail merge.",
    answer: "Mail merge is a way to take a letter you have written and send it to a whole bunch of people, personalizing it with information about them so they might think that you typed that letter personally for them. A mail merge can also be a quick way to take a list of people\u0027s mailing addresses and generate labels or envelopes with the address for a different person on each label or envelope. The process involves a main document (the letter) and a data source (the list of recipients). Merge fields are placed in the main document where personalized information should appear. Benefits: (1) The Mail Merge feature makes it easy to send the same letter to a large number of people. (2) We do not have to type each recipient\u0027s name separately. (3) We need to proofread only the main document. (4) It is economical and saves a lot of time. (5) It is one of the fastest ways to produce hundreds of personalised letters."
