    answer: "General guidelines for strong passwords: (1) Password must be a combination of uppercase alphabet, lowercase alphabet, digits, and special symbols. (2) It must be 6 to 8 characters long. (3) It must not be the name of family members, friends, pets, etc. (4) It must not be any dictionary words. (5) It must not be your date of birth or any personal information that can be guessed easily. (6) Change your password frequently, at least every 2-3 weeks. (7) Use different passwords for different accounts."
