    question: "In the context of Database Management System, write a short note on the following: (a) Database (b) Table (c) Field (d) Composite Primary Key",
    answer: "(a) Database: A database is an organized collection of data that can be easily accessed, managed and updated. It stores data in tables that are related to each other. (b) Table: A table is a collection of related data organized in rows (records) and columns (fields). Each table represents a specific entity. (c) Field: A field is a single piece of information in a table. It represents a column that contains a specific type of data for all records. (d) Composite Primary Key: A composite primary key is a combination of two or more columns that uniquely identifies each row in a table. Together they form a unique identifier."
