    answer: "Database Management System (DBMS) is a collection of programs that enable users to create, manipulate, maintain databases and control all access to the database. The primary goal of DBMS is to provide an environment that is both convenient and efficient for users to retrieve and store information. Advantages of using DBMS for school: (1) In school, DBMS is used to store data about students, teachers, and any other related information at a centralized location. (2) It provides security to the personal information of the school and stored data. (3) It reduces data redundancy and maintains consistency."
