    question: "(a) State the relationship and difference between a primary and foreign key. (b) Write SQL command to create the table VEHICLES: Reg_No char(15) Primary Key, Reg_Date date, Owner_Name varchar(20), Address varchar(40). Also add some information.",
    answer: "(a) Relationship: A foreign key is the column or set of columns in one table that references the primary key column in another table. The primary key uniquely identifies each record in a table. Difference: A primary key cannot accept null values, while a foreign key can accept multiple null values. A table can have only one primary key but can have multiple foreign keys. (b) CREATE TABLE VEHICLES (Reg_No char(15) Primary Key, Reg_Date date, Owner_Name varchar(20), Address varchar(40)); INSERT INTO VEHICLES VALUES (\u0027101\u0027, \u00272023-12-14\u0027, \u0027LearnCSE\u0027, \u0027Bangalore\u0027);"
